import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {createPortal} from 'react-dom';
function Field({title,children}){return <div className="ashby-application-form-field-entry"><label className="ashby-application-form-question-title">{title}</label>{children}</div>;}
function School(){const [query,setQuery]=useState(''),[open,setOpen]=useState(false),[saved,setSaved]=useState('');return <div><label className="ashby-application-form-question-title">School</label><div><input role="combobox" className="ashby-application-form-input-autocomplete" placeholder="Search schools..." aria-expanded={open} aria-controls={open?'schools':undefined} value={query} onChange={e=>{setQuery(e.target.value);setOpen(true);}} onKeyDown={e=>{if(e.key==='Escape')setOpen(false);}} onBlur={()=>{setQuery(saved);setOpen(false);}}/>{open&&createPortal(<div role="listbox" id="schools">{(query==='University of Michigan'?['University of Michigan','University of Michigan–Flint']:[]).map(name=><div role="option" key={name} onMouseDown={e=>e.preventDefault()} onClick={()=>{setSaved(name);setQuery(name);setOpen(false);}}><span className="_canonicalSchoolResultName_fixture">{name}</span><span>United States</span><span>umich.edu</span></div>)}{query!=='University of Michigan'&&<p>No results</p>}</div>,document.body)}</div></div>;}
function YesNo(){const [answer,setAnswer]=useState('');return <div className="ashby-application-form-input-yesno">{['yes','no'].map(v=><button key={v} data-option={v} aria-pressed={answer===v} onClick={()=>setAnswer(v)}>{v==='yes'?'Yes':'No'}</button>)}<input type="checkbox" tabIndex={-1} hidden checked={answer==='yes'} readOnly/></div>;}
function Dates({title}){return <div><label className="ashby-application-form-question-title">{title}</label><div><div><select defaultValue=""><option value="" disabled hidden>Month...</option><option value="5">May</option><option value="9">September</option></select></div><div><select defaultValue=""><option value="" disabled hidden>Year...</option><option value="2026">2026</option><option value="2027">2027</option></select></div></div></div>;}
function App(){return <form onSubmit={e=>{e.preventDefault();window.submitted=true;}}><div className="ashby-application-form-autofill-input-root"><input type="file" aria-label="Autofill from resume"/></div><Field title="Full Legal Name"><input/></Field><Field title="Resume"><input type="file" accept=".txt"/></Field><Field title="Education History"><School/><div><label htmlFor="degree">Degree</label><input id="degree"/></div><div><label htmlFor="major">Field of Study</label><input id="major"/></div><Dates title="Start Date"/><Dates title="End Date"/><label><input type="checkbox" id="_systemfield_education_history-isCurrent"/>Still Student?</label></Field><Field title="What is your graduation date?"><input placeholder="Pick date..."/></Field><Field title="Requesting visa sponsorship?"><YesNo/></Field><Field title="Willing to relocate to NYC?"><YesNo/></Field><Field title="Share something you’ve built that you’re proud of."><input/></Field><label><input type="checkbox"/>I agree to terms</label><fieldset><legend>Communication consent</legend><label><input type="radio" name="communicationConsent" value="yes"/>Yes</label></fieldset><button>Submit Application</button></form>;}
createRoot(document.getElementById('root')).render(<App/>);
